589 |   /**
590 |    * Detect manually wrapped and indented strings by checking for line break followed by whitespace.
591 |    *
592 |    * @param {string} str
593 |    * @returns {boolean}
594 |    */
595 |   preformatted(str) {
596 |     return /\n[^\S\r\n]/.test(str);
597 |   }
598 | 
599 |   /**
600 |    * Format the "item", which consists of a term and description. Pad the term and wrap the description, indenting the following lines.
601 |    *
602 |    * So "TTT", 5, "DDD DDDD DD DDD" might be formatted for this.helpWidth=17 like so:
603 |    *   TTT  DDD DDDD
604 |    *        DD DDD
605 |    *
606 |    * @param {string} term
607 |    * @param {number} termWidth
608 |    * @param {string} description
609 |    * @param {Help} helper
610 |    * @returns {string}
611 |    */
612 |   formatItem(term, termWidth, description, helper) {
613 |     const itemIndent = 2;
614 |     const itemIndentStr = ' '.repeat(itemIndent);
615 |     if (!description) return itemIndentStr + term;
616 | 
617 |     // Pad the term out to a consistent width, so descriptions are aligned.
618 |     const paddedTerm = term.padEnd(
619 |       termWidth + term.length - helper.displayWidth(term),
620 |     );
621 | 
622 |     // Format the description.
623 |     const spacerWidth = 2; // between term and description
624 |     const helpWidth = this.helpWidth ?? 80; // in case prepareContext() was not called
625 |     const remainingWidth = helpWidth - termWidth - spacerWidth - itemIndent;
626 |     let formattedDescription;
627 |     if (
628 |       remainingWidth < this.minWidthToWrap ||
629 |       helper.preformatted(description)
630 |     ) {
631 |       formattedDescription = description;
632 |     } else {
633 |       const wrappedDescription = helper.boxWrap(description, remainingWidth);
634 |       formattedDescription = wrappedDescription.replace(
635 |         /\n/g,
636 |         '\n' + ' '.repeat(termWidth + spacerWidth),
637 |       );
638 |     }
639 | 
640 |     // Construct and overall indent.
641 |     return (
642 |       itemIndentStr +
643 |       paddedTerm +
644 |       ' '.repeat(spacerWidth) +
645 |       formattedDescription.replace(/\n/g, `\n${itemIndentStr}`)
646 |     );
647 |   }
648 | 
649 |   /**
650 |    * Wrap a string at whitespace, preserving existing line breaks.
651 |    * Wrapping is skipped if the width is less than `minWidthToWrap`.
652 |    *
653 |    * @param {string} str
654 |    * @param {number} width
655 |    * @returns {string}
656 |    */
657 |   boxWrap(str, width) {
658 |     if (width < this.minWidthToWrap) return str;
659 | 
660 |     const rawLines = str.split(/\r\n|\n/);
661 |     // split up text by whitespace
662 |     const chunkPattern = /[\s]*[^\s]+/g;
663 |     const wrappedLines = [];
664 |     rawLines.forEach((line) => {
665 |       const chunks = line.match(chunkPattern);
666 |       if (chunks === null) {
667 |         wrappedLines.push('');
668 |         return;
669 |       }
670 | 
671 |       let sumChunks = [chunks.shift()];
672 |       let sumWidth = this.displayWidth(sumChunks[0]);
673 |       chunks.forEach((chunk) => {
674 |         const visibleWidth = this.displayWidth(chunk);
675 |         // Accumulate chunks while they fit into width.
676 |         if (sumWidth + visibleWidth <= width) {
677 |           sumChunks.push(chunk);
678 |           sumWidth += visibleWidth;
679 |           return;
680 |         }
681 |         wrappedLines.push(sumChunks.join(''));
682 | 
683 |         const nextChunk = chunk.trimStart(); // trim space at line break
684 |         sumChunks = [nextChunk];
685 |         sumWidth = this.displayWidth(nextChunk);
686 |       });
687 |       wrappedLines.push(sumChunks.join(''));
688 |     });
689 | 
690 |     return wrappedLines.join('\n');
691 |   }
692 | }
