694 | /**
695 |  * Strip style ANSI escape sequences from the string. In particular, SGR (Select Graphic Rendition) codes.
696 |  *
697 |  * @param {string} str
698 |  * @returns {string}
699 |  * @package
700 |  */
701 | 
702 | function stripColor(str) {
703 |   // eslint-disable-next-line no-control-regex
704 |   const sgrPattern = /\x1b\[\d*(;\d*)*m/g;
705 |   return str.replace(sgrPattern, '');
706 | }
