261 |     this.negativeOptions = new Map();
262 |     this.dualOptions = new Set();
263 |     options.forEach((option) => {
264 |       if (option.negate) {
265 |         this.negativeOptions.set(option.attributeName(), option);
266 |       } else {
267 |         this.positiveOptions.set(option.attributeName(), option);
268 |       }
269 |     });
270 |     this.negativeOptions.forEach((value, key) => {
271 |       if (this.positiveOptions.has(key)) {
272 |         this.dualOptions.add(key);
273 |       }
274 |     });
