315 | function splitOptionFlags(flags) {
316 |   let shortFlag;
317 |   let longFlag;
318 |   // short flag, single dash and single character
319 |   const shortFlagExp = /^-[^-]$/;
320 |   // long flag, double dash and at least one character
321 |   const longFlagExp = /^--[^-]/;
322 | 
323 |   const flagParts = flags.split(/[ |,]+/).concat('guard');
324 |   // Normal is short and/or long.
325 |   if (shortFlagExp.test(flagParts[0])) shortFlag = flagParts.shift();
326 |   if (longFlagExp.test(flagParts[0])) longFlag = flagParts.shift();
327 |   // Long then short. Rarely used but fine.
328 |   if (!shortFlag && shortFlagExp.test(flagParts[0]))
329 |     shortFlag = flagParts.shift();
330 |   // Allow two long flags, like '--ws, --workspace'
331 |   // This is the supported way to have a shortish option flag.
332 |   if (!shortFlag && longFlagExp.test(flagParts[0])) {
333 |     shortFlag = longFlag;
334 |     longFlag = flagParts.shift();
335 |   }
336 | 
337 |   // Check for unprocessed flag. Fail noisily rather than silently ignore.
338 |   if (flagParts[0].startsWith('-')) {
339 |     const unsupportedFlag = flagParts[0];
340 |     const baseError = `option creation failed due to '${unsupportedFlag}' in option flags '${flags}'`;
341 |     if (/^-[^-][^-]/.test(unsupportedFlag))
342 |       throw new Error(
343 |         `${baseError}
344 | - a short flag is a single dash and a single character
345 |   - either use a single dash and a single character (for a short flag)
346 |   - or use a double dash for a long option (and can have two, like '--ws, --workspace')`,
347 |       );
348 |     if (shortFlagExp.test(unsupportedFlag))
349 |       throw new Error(`${baseError}
350 | - too many short flags`);
351 |     if (longFlagExp.test(unsupportedFlag))
352 |       throw new Error(`${baseError}
353 | - too many long flags`);
354 | 
355 |     throw new Error(`${baseError}
356 | - unrecognised flag format`);
357 |   }
358 |   if (shortFlag === undefined && longFlag === undefined)
359 |     throw new Error(
360 |       `option creation failed due to no flags found in '${flags}'.`,
361 |     );
362 | 
363 |   return { shortFlag, longFlag };
364 | }
