580 |   padWidth(cmd, helper) {
581 |     return Math.max(
582 |       helper.longestOptionTermLength(cmd, helper),
583 |       helper.longestGlobalOptionTermLength(cmd, helper),
584 |       helper.longestSubcommandTermLength(cmd, helper),
585 |       helper.longestArgumentTermLength(cmd, helper),
586 |     );
587 |   }
